import csv,re,random
COLS=re.findall(r'^\s*\("([^"]+)",', open('CLAUDE.md').read().split('COLUMNS = [')[1].split(']\n```')[0], re.M)
P='data/papers_test/md_agents/Knox & Clarke 2004 Cunninghamia_primary juvenile period.md'
pg=open(P).read().split('<!-- PAGE BREAK -->')
def table(text,pat):
    out=[];on=False
    for l in text.split('\n'):
        if not on and re.search(pat,l): on=True; continue
        if on:
            if l.startswith('|'):
                if re.match(r'^\|[-| ]+\|$',l): continue
                out.append([c.strip() for c in l.strip()[1:-1].split('|')])
            elif out: break
    return out
t1=table(pg[2],r'^\*\*Table 1')[1:]; t2=table(pg[3],r'^\*\*Table 2')[1:]
print(len(t1),len(t2))
def name(s):
    s=s.replace('*','').strip(); parts=s.split(' ',1); g,rest=parts
    m=re.match(r'(\S+) ((?:subsp|var)\. \S+)$',rest)
    if m: return g,m.group(1),m.group(2)
    return g,rest,''
T1={name(r[0]):r for r in t1}
SRC="Knox, K.J.E. & Clarke, P.J. (2004) Fire response syndromes of shrubs in grassy woodlands in the New England Tableland Bioregion. Cunninghamia 8(3): 348–353."
FN="Knox & Clarke 2004 Cunninghamia_primary juvenile period"
def val(v):
    v=v.replace('\\*','').strip()
    if v in('','n.a.'): return ''
    m=re.fullmatch(r'Not flowering after ([\d.]+) years',v)
    if m: return '>'+m.group(1)
    m=re.fullmatch(r'(<|>)? ?([\d.]+) years',v); assert m,v
    return (m.group(1) or '')+m.group(2)
rows=[]
for sp,fr,pjp,sjp in t2:
    g,s,ss=name(sp)
    r={c:'' for c in COLS}
    r.update({'Genus':g,'Species':s,'subsp':ss,'scientific_name':f'{g} {s}','Source':SRC,'File_name':FN,
      'fire_response categorical_surv1':{'resprouter':'resprouter','obligate seeder':'obligate'}[fr],
      'Location_name':'Imbota Nature Reserve / Booroolong Nature Reserve','Fire_type':'experimental burn','Fire_season_categorical':'Spring/Autumn'})
    n=[]
    t=T1.get((g,s,ss))
    if t:
        if t[4]!='n.a.': r['resprouter_type']=t[4]
        n.append(f"Table 1 p. 350: survival {t[2]}% (n = {t[3].strip('()')}) after 100% leaf scorch; resprouter >70% survival, obligate seeder <30% (Gill & Bradstock 1992)")
    else: n.append("species not in Table 1; fire response from Table 2 p. 351")
    r['primary_juvenile_period']=val(pjp); r['secondary_juvenile_period']=val(sjp)
    if r['secondary_juvenile_period']: r['Time_unit']='years'
    n.append("Table 2 p. 351; primary juvenile period from naturally recruiting populations and field-sown seed at burn sites 1.5-3 years post-fire, observed August 2002 and September 2003")
    if '>' in pjp+sjp or 'Not flowering' in pjp+sjp: n.append("'Not flowering after N years' written as >N")
    if '\\*' in pjp or '\\*' in sjp: n.append("'*' in table = no data available")
    if g=='Indigofera' and s=='australis': n.append("Discussion p. 352 says primary juvenile period appears to be more than four years, Table 2 and Results give 4 years; Table 2 value used")
    if s=='setulosai': n.append("species epithet as printed (setulosai)")
    n.append("data pooled over Imbota NR (experimental burns Spring 1999; rainfall 790 mm/yr, Armidale) and Booroolong NR (experimental burns Autumn 2000; rainfall 884 mm/yr, Guyra), not split by site; no coordinates given; fire intensity not measured, expected low (8 t/ha fuel) and moderate (16 t/ha fuel) in two halves of each burn")
    r['Notes']='; '.join(n); rows.append(r)
with open('data/inference_test/results/opus-5-5.csv','a',newline='',encoding='utf-8') as f:
    csv.DictWriter(f,COLS,lineterminator='\n').writerows(rows)
print(len(rows))
for r in random.sample(rows,3): print({k:v for k,v in r.items() if v and k not in('Source','Notes')})
