import csv,re,random,json
COLS=re.findall(r'^\s*\("([^"]+)",', open('CLAUDE.md').read().split('COLUMNS = [')[1].split(']\n```')[0], re.M)
t=open('data/papers_test/md_agents/Kubiak Cunn 2009.md').read().split('<!-- PAGE BREAK -->')
SRC="Kubiak, P.J. (2009) Fire responses of bushland plants after the January 1994 wildfires in northern Sydney. Cunninghamia 11(1): 131–165."
FN="Kubiak Cunn 2009"
LCR=dict(Latitude='-33.75',Longitude='151.0833',Location_name='')
NL=dict(Latitude='',Longitude='',Location_name='Narrabeen Lagoon catchment')
JN=dict(Latitude='',Longitude='',Location_name='Lane Cove River catchment / Narrabeen Lagoon catchment')
FIRE={'Fire_type':'wildfire','Fire_season_categorical':'Summer','Fire_severity_categorical':'High'}
FIRENOTE="fire: wildfires of 6-8 January 1994, generally very high intensity with patches burnt at low or moderate intensity (pp. 133-136); all responses for plants with 100% leaf scorch"
CODEDEF="codes: R = majority of adults resprouted, K = majority killed, r = small proportion resprouted, k = small proportion killed, p = probably (80-90% sure), ? = possibly (50-70% sure)"
def num(x): 
    s=f"{x:.3f}".rstrip('0').rstrip('.'); return s
def parse(cell):
    s=re.sub(r'</?u>|\*\*','',cell).strip()
    if s.startswith('At least'): 
        m=re.search(r'(\d+)',s); return dict(lo=m.group(1),hi=None,plus=True,unit='y',approx=False)
    if s.startswith('Less than'):
        m=re.search(r'(\d+)',s); return dict(lo=m.group(1),hi=None,plus=False,lt=True,unit='y',approx=False)
    m=re.match(r'^(c\.\s?)?\??(\d+(?:\.\d+)?)(\+)?(?:\s?[–-]\s?(\d+(?:\.\d+)?)(\+)?)?\s?([wy])',s)
    if not m: return None
    return dict(lo=m.group(2),hi=m.group(4),plus=bool(m.group(3) or m.group(5)),unit=m.group(6),approx=bool(m.group(1)))
def fmt(p,target):  # target 'y' fixed years, or None = paper unit
    if p is None: return '',None
    f=(lambda v:v) if (target is None or p['unit']=='y') else (lambda v:num(float(v)/52))
    if p.get('lt'): return '<'+f(p['lo']),p['unit']
    if p['plus']: return '>'+f(p['lo']),p['unit']
    v=f(p['lo'])+('-'+f(p['hi']) if p['hi'] else '')
    return v,p['unit']
def name(raw):
    notes=[]; s=raw; exotic=False
    if s.startswith('(*?)'): s=s[4:]; notes.append("printed '(*?)': possibly exotic")
    if s.startswith('*'): s=s[1:]; exotic=True
    for q in re.findall(r'\s*(\((?:s\.lat\.|s\.str\.|syn\.[^)]*)\))',s):
        s=s.replace(q,'').strip(); notes.append(f"name qualifier {q}")
    g,rest=s.split(' ',1); infra=''
    m=re.match(r'^(.+?) ((?:subsp|var|cv)\. .+)$',rest)
    if m: rest,infra=m.group(1),m.group(2)
    if exotic:
        if infra: notes.append(f"infraspecific name {infra} (subsp column holds exotic '*')")
        infra='*'
    return g,rest,infra,notes
def frcode(code):
    if not code: return '',[]
    m=re.match(r'^((?:\?\s?|p)?[RKrk])(?:\s*/\s*((?:\?|p)?[RKrk]))?',code)
    if not m: return '',[f"fire response cell: '{code}'"]
    parts=[x.replace(' ','') for x in m.groups() if x]
    core=[x.lstrip('?p') for x in parts]
    n=[f"fire response code printed '{code}'" if len(code)<12 else f"fire response cell printed '{code}'"]
    if len(core)==1:
        out={'R':'resprouter','K':'obligate'}.get(core[0],core[0])
    else: out='/'.join(core)
    return out,n
pages_out={}
batches=[(15,24),(25,34),(35,35)]
allrows=[];total=0
for b0,b1 in batches:
    rows=[]
    for i in range(b0,b1+1):
        jp=130+i
        for l in t[i-1].split('\n'):
            if not l.startswith('|') or re.match(r'^\|[-| ]+\|$',l): continue
            c=[x.strip() for x in l.strip()[1:-1].split('|')]
            if c[0]=='Family': continue
            fam,sp,peak,lcr,nl,seed,flr,fls,frr,frs,pjp,sjp=c
            g,s,infra,nn=name(sp)
            base={k:'' for k in COLS}
            base.update({'Genus':g,'Species':s,'subsp':infra,'Family':fam,'Source':SRC,'File_name':FN,**FIRE})
            base['scientific_name']=f'{g} {s}'+(' *' if infra=='*' else '')
            tn=[]; tv={}
            def tcol(col,cell,label,target):
                if not cell: return
                if '<u>' in cell:
                    tn.append(f"{label} '{re.sub(r'</?u>','',cell)}' underlined in paper (unclear whether from seed or resprout; spans Resp and Seed columns), kept in Notes only"); return 'u'
                p=parse(cell)
                if p is None: tn.append(f"{label} cell: '{cell}'"); return
                v,u=fmt(p,target); tv[col]=v
                if target=='y' and p['unit']=='w': tn.append(f"{col} converted from {p['lo']}{'-'+p['hi'] if p['hi'] else ''} weeks")
                extra=re.sub(r'\*\*','',cell)
                tn.append(f"{label} printed '{cell.replace('**','')}'"+(' (bold = sizable proportion of population flowering)' if '**' in cell else ''))
                if col=='secondary_juvenile_period': tv['Time_unit']={'w':'weeks','y':'years'}[u]
            if peak: tn.append(f"post-fire peak {peak}")
            if seed: tn.append(f"seedlings first observed {seed} after fire")
            u1=tcol('Time to first flower production resprout_repr3a',flr,'first flowering of resprouts','y')
            u2=tcol('Age at first flower production from seed_repr3',fls if not (u1=='u' and fls==flr) else '','first flowering from seed','y')
            for lab,cell in (('first fruiting of resprouts',frr),('first fruiting from seed',frs)):
                if cell and not ('<u>' in cell and cell==frr and lab.endswith('seed')):
                    tn.append(f"{lab} {re.sub(r'</?u>','',cell)}"+(' (underlined: unclear whether from seed or resprout)' if '<u>' in cell else ''))
            tcol('primary_juvenile_period',pjp,'primary juvenile period','y')
            tcol('secondary_juvenile_period',sjp,'secondary juvenile period',None)
            if tv or tn: tn.append("time values in weeks (w) or years (y) after the January 1994 fires; c. = approximately; (shd) shedding seed or spores, grn/imm green or immature fruit, ri ripe fruit, (1) one plant")
            srcnote=f"Appendix 1 p. {jp}"
            fl,fln=frcode(lcr); fn_,fnn=frcode(nl)
            has_t=bool(tv) or bool([x for x in tn])
            def mkrow(site,fr,frn,times):
                r=dict(base); r.update(site); r['fire_response categorical_surv1']=fr
                n=[srcnote]+nn+frn
                if fr or frn: n.append(CODEDEF)
                if times: r.update(tv); n+=tn
                n.append(FIRENOTE)
                if site is NL: n.append("paper gives coordinates only for the Lane Cove River valley; Narrabeen Lagoon catchment c. 15 km NE; NL observations March-October 1994")
                if site is LCR: n.append("Lane Cove River catchment; coordinates lat 33° 45' S, long 151° 05' E (p. 133); observations mainly January 1994-October 1999")
                r['_n']=n; return r
            sites=[(LCR,fl,fln,lcr),(NL,fn_,fnn,nl)]
            present=[x for x in sites if x[3]]
            if len(present)==2:
                for st,f,fnote,_ in present: rows.append(mkrow(st,f,fnote+(["timing values not split by catchment; on shared Lane Cove River / Narrabeen Lagoon row"] if has_t else []),False))
                if has_t: rows.append(mkrow(JN,'',['fire response per catchment on the site rows; timing values in Appendix 1 not split by catchment'],True))
            elif len(present)==1:
                st,f,fnote,_=present[0]
                rows.append(mkrow(st,f,fnote+(["timing values not split by catchment in Appendix 1; assigned to the only catchment with a fire response record"] if has_t else []),True))
            else:
