CODEDEF="codes: R = majority of adults resprouted, K = majority killed, r = small proportion resprouted, k = small proportion killed, p = probably (80-90% sure), ? = possibly (50-70% sure)"
def num(x): 
    s=f"{x:.3f}".rstrip('0').rstrip('.'); return s
def parse(cell):
    s=re.sub(r'</?u>|\*\*','',cell).strip()
    if s.startswith('At least'): 
        m=re.search(r'(\d+)',s); return dict(lo=m.group(1),hi=None,plus=True,unit='y',approx=False)
    if s.startswith('Less than'):
        m=re.search(r'(\d+)',s); return dict(lo=m.group(1),hi=None,plus=False,lt=True,unit='y',approx=False)
    m=re.match(r'^(c\.\s?)?\??(\d+(?:\.\d+)?)(\+)?(?:\s?[–-]\s?(\d+(?:\.\d+)?)(\+)?)?\s?([wy])',s)
    if not m: return None
    return dict(lo=m.group(2),hi=m.group(4),plus=bool(m.group(3) or m.group(5)),unit=m.group(6),approx=bool(m.group(1)))
def fmt(p,target):  # target 'y' fixed years, or None = paper unit
    if p is None: return '',None
    f=(lambda v:v) if (target is None or p['unit']=='y') else (lambda v:num(float(v)/52))
    if p.get('lt'): return '<'+f(p['lo']),p['unit']
    if p['plus']: return '>'+f(p['lo']),p['unit']
    v=f(p['lo'])+('-'+f(p['hi']) if p['hi'] else '')
    return v,p['unit']
def name(raw):
    notes=[]; s=raw; exotic=False
    if s.startswith('(*?)'): s=s[4:]; notes.append("printed '(*?)': possibly exotic")
    if s.startswith('*'): s=s[1:]; exotic=True
    for q in re.findall(r'\s*(\((?:s\.lat\.|s\.str\.|syn\.[^)]*)\))',s):
        s=s.replace(q,'').strip(); notes.append(f"name qualifier {q}")
    g,rest=s.split(' ',1); infra=''
    m=re.match(r'^(.+?) ((?:subsp|var|cv)\. .+)$',rest)
    if m: rest,infra=m.group(1),m.group(2)
    if exotic:
        if infra: notes.append(f"infraspecific name {infra} (subsp column holds exotic '*')")
        infra='*'
    return g,rest,infra,notes
def frcode(code):
    if not code: return '',[]
    m=re.match(r'^((?:\?\s?|p)?[RKrk])(?:\s*/\s*((?:\?|p)?[RKrk]))?',code)
