import csv,re,random,collections
COLS=re.findall(r'^\s*\("([^"]+)",', open('CLAUDE.md').read().split('COLUMNS = [')[1].split(']\n```')[0], re.M)
FN='nswfrrd_v1.3a_pdfvers_sppdata'
t=open('data/papers_test/md_agents/'+FN+'.md').read().split('<!-- PAGE BREAK -->')
A=[];B=[]
for i,p in enumerate(t,1):
    for l in p.split('\n'):
        if l.startswith('|') and not re.match(r'^\|[-| ]+\|$',l):
            c=[x.strip() for x in l.strip()[1:-1].split('|')]
            if c[0]=='Species': continue
            (A if len(c)==10 else B).append((i,c))
recs=list(zip(A,B))
def name(s):
    n=[]
    s2=re.sub(r'(\w)- (\w)',r'\1-\2',s)
    if s2!=s: n.append(f"name printed '{s}' (hyphen split across line), joined")
    m=re.match(r'^(\S+) (.+?)(?: ((?:subsp\.?|var\.?|forma|nothosubsp\.) .+))?$',s2)
    return m.group(1),m.group(2),(m.group(3) or ''),n
