    groups.setdefault((a[0],exotic),[]).append((pa,a,pb,b))
rows=[];batchrows=collections.defaultdict(list)
for (nm,exotic),lst in groups.items():
    g,s,infra,nn=name(nm)
    r={c:'' for c in COLS}
    if exotic:
        if infra: nn.append(f"infraspecific name {infra} (subsp column holds exotic '*')")
        infra='*'
    r.update({'Genus':g,'Species':s,'subsp':infra,'scientific_name':f'{g} {s}'+(' *' if exotic else ''),'Source':FN,'File_name':FN})
    fams={a[2] for _,a,_,_ in lst}; r['Family']=' / '.join(sorted(f for f in fams if f))
    frs=[a[3] for _,a,_,_ in lst]
    r['fire_response categorical_surv1']=frs[0] if len(set(frs))==1 else ' / '.join(frs)
    notes=nn[:]
    for k,(pa,a,pb,b) in enumerate(lst):
        pre=f"record {k+1}: " if len(lst)>1 else ''
        x=[f"pp. {pa}-{pb}"]
        if a[1]: x.append(f"synonym {a[1]}")
        x.append(f"fire response '{a[3]}' (code not defined in document, copied as printed)")
        if a[4]: x.append(f"comments on regeneration: {a[4]}")
        if b[4]: x.append(f"primary juvenile {b[4]} (unit not stated)")
        if b[5]: x.append(f"secondary juvenile period {b[5]} (unit not stated)")
        if b[6]: x.append(f"recommended minimum interval {b[6]} (unit not stated)")
        if b[1]: x.append(f"VA group {b[1]}")
        if exotic: x.append("Distribution: NSW printed 'Exotic'")
        notes.append(pre+', '.join(x))
    if len(lst)>1: notes.append(f"{len(lst)} records for this taxon in the document, merged; fire responses joined in record order")
    notes.append("no citation, study site or fire printed in document; Source = file stem")
    r['Notes']='; '.join(notes)
    rows.append(r); batchrows[(lst[0][0]-1)//10].append(r)
print(len(recs),len(rows))
with open('data/inference_test/results/opus-5-5.csv','a',newline='',encoding='utf-8') as f:
    w=csv.DictWriter(f,COLS,lineterminator='\n')
    for b in sorted(batchrows):
        w.writerows(batchrows[b]); f.flush()
        print(f"    pages {b*10+1}-{min(b*10+10,205)} of 205 | rows {len(batchrows[b])}")
random.seed(3)
for r in random.sample(rows,3)+[x for x in rows if x['Genus']=='Banksia' and x['Species']=='marginata']:
    print({k:v for k,v in r.items() if v and k not in('Source','File_name')})
